import { computed, ref } from "vue";

export const App = () => {
  const count = ref(0);
  const doubled = computed(() => count.value * 2);
  const increment = () => {
    count.value += 1;
  };

  return (
    <section>
      <button onClick={increment}>Increment</button>
      <p>{count.value}</p>
      <p>{doubled.value}</p>
    </section>
  );
};

