import { ref } from "vue";

type TsxCounterProps = {
  label?: string;
};

const TsxCounter = ({ label = "TSX" }: TsxCounterProps, _ctx: Ctx) => {
  const count = ref(0);
  const increment = () => count.value++;
  return (
    <button type="button" class="tsx-counter" onClick={increment}>
      {label}: {count.value}
    </button>
  );
};

export default TsxCounter;

const GenericList = <T extends string,>({ items }: { items: Array<T> }) => {
  const first = items[0];
  return <ul>{first}</ul>;
};

export default GenericList;

const Greeting = (props, { emit }) => {
  const shout = () => emit("shout");
  return <button onClick={shout}>{props.label}</button>;
};

const Spread = (props, ...rest) => {
  const first = rest[0];
  return <div>{first}</div>;
};

const First = ({ a }) => {
  const one = a;
  return <p>{one}</p>;
};
const Second = ({ b }) => {
  const two = b;
  return <p>{two}</p>;
};

const Fallback = () => <i/>;
const App = ({ slot = <Fallback /> }) => {
  const node = slot;
  return <div>{node}</div>;
};

const AsyncPanel = async ({ id }) => {
  const data = await load(id);
  return <div>{data}</div>;
};

const SyncApp = () => {
  const data = load();
  return <div>{data}</div>;
};

const Counter = ({ label = "TSX", step }) => {
  const next = step;
  return <button>{label}{next}</button>;
};

const Renamed = ({ label: text }) => {
  const shown = text;
  return <span>{shown}</span>;
};

const Spread = ({ label, ...rest }) => {
  const extra = rest;
  return <div>{label}{extra}</div>;
};

const Computed = ({ label, [dynamic]: value }) => {
  const shown = value;
  return <div>{label}{shown}</div>;
};

const Plain = (props) => {
  const shown = props.label;
  return <div>{shown}</div>;
};

const WithContext = ({ label }, { emit }) => {
  const shout = () => emit("shout");
  return <button onClick={shout}>{label}</button>;
};

type Props = { label?: string };

const Typed = ({ label = "TSX" }: Props) => {
  const shown = label;
  return <div>{shown}</div>;
};

import Child from "./Child";
export const suffix = "!";
export function Card(props: { label: string }) {
    const label = props.label + suffix;
    return <Child label={label}/>;
}
export default <T extends string,>(props: { label: T }) => <Card label={props.label}/>;

import { ref } from "vue";
export const Stateful = () => {
    const count = ref(0);
    const increment = () => count.value++;
    return <button onClick={increment}>{count.value}</button>;
};
export const Pure = (props: {label:string}) => <i>{props.label}</i>;
export default Stateful;

export const App = ({ slot = <i data-kind="fallback"/> }: {slot?: any}) => {
    const kind = slot.type;
    return <div>{kind}</div>;
};
export default App;

export default function marker() { return "retained"; }
export const Typed = (props: { label: string; amount?: number }) => {
    const read = () => props.label;
    return <p>{read()}</p>;
};

